/**
 * Exhaustive role×action sweep of `ROLE_MATRIX`, including ownership
 * escalations and the cross-tenant denial.
 */
import { describe, expect, it } from "vitest";
import { ROLE_MATRIX, can, canAll, explain } from "@/lib/permissions";
import type { IssueId, ProjectId } from "@/types/common";
import { ROLES, ROLE_RANK, type Role } from "@/types/member";
import type { PermissionAction, PermissionResource } from "@/types/permission";
import { ALICE, BOB, ORG_A, ORG_B, makeActor } from "../helpers/factories";

const ACTIONS = Object.keys(ROLE_MATRIX) as readonly PermissionAction[];

/**
 * A resource in ORG_A owned by nobody the actor is, so the sweep measures the
 * matrix alone and never trips an ownership escalation.
 */
const foreignOwned: PermissionResource = {
  kind: "issue",
  orgId: ORG_A,
  projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId,
  issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
  authorId: BOB,
  assigneeId: BOB,
};

const orgResource: PermissionResource = { kind: "organization", orgId: ORG_A };

describe("permissions matrix", () => {
  it("covers every declared action", () => {
    expect(ACTIONS.length).toBeGreaterThan(20);
    for (const action of ACTIONS) {
      expect(ROLES).toContain(ROLE_MATRIX[action]);
    }
  });

  it("grants exactly the roles at or above the required rank", () => {
    for (const action of ACTIONS) {
      const required = ROLE_MATRIX[action];
      for (const role of ROLES) {
        const expected = ROLE_RANK[role] >= ROLE_RANK[required];
        expect(
          can(makeActor({ role, userId: ALICE }), action, foreignOwned),
          `${role} → ${action}`,
        ).toBe(expected);
      }
    }
  });

  it("reports `granted_by_role` and `denied_by_role` as the reason", () => {
    expect(explain(makeActor({ role: "owner" }), "org:delete", orgResource).reason).toBe(
      "granted_by_role",
    );
    expect(explain(makeActor({ role: "admin" }), "org:delete", orgResource).reason).toBe(
      "denied_by_role",
    );
  });

  it("denies every action across a tenant boundary, whatever the role", () => {
    for (const role of ROLES) {
      const foreign = makeActor({ role, orgId: ORG_B });
      for (const action of ACTIONS) {
        expect(can(foreign, action, orgResource), `${role} → ${action}`).toBe(false);
      }
    }
    expect(explain(makeActor({ orgId: ORG_B }), "org:read", orgResource).reason).toBe(
      "denied_cross_tenant",
    );
  });

  it("checks the tenant boundary before the staff bypass", () => {
    const staff = makeActor({ orgId: ORG_B, isPlatformStaff: true, role: "owner" });
    expect(can(staff, "org:read", orgResource)).toBe(false);
    expect(explain(staff, "org:read", orgResource).reason).toBe("denied_cross_tenant");
  });

  it("lets platform staff bypass the matrix inside their own tenant", () => {
    const staff = makeActor({ role: "viewer", isPlatformStaff: true });
    for (const action of ACTIONS) {
      expect(can(staff, action, orgResource), action).toBe(true);
    }
    expect(explain(staff, "org:delete", orgResource).reason).toBe("granted_by_staff");
  });

  it("puts billing and deletion behind the owner role alone", () => {
    for (const action of ["org:delete", "org:manage_billing", "project:delete"] as const) {
      expect(ROLE_MATRIX[action]).toBe("owner");
      expect(can(makeActor({ role: "admin" }), action, orgResource)).toBe(false);
      expect(can(makeActor({ role: "owner" }), action, orgResource)).toBe(true);
    }
  });

  it("keeps the everyday read actions available to a viewer", () => {
    for (const action of [
      "org:read",
      "member:read",
      "project:read",
      "issue:read",
      "comment:read",
      "notification:read",
    ] as const) {
      expect(ROLE_MATRIX[action], action).toBe("viewer");
      expect(can(makeActor({ role: "viewer" }), action, orgResource), action).toBe(true);
    }
  });

  it("holds the audit trail above viewer, unlike the other reads", () => {
    expect(ROLE_MATRIX["activity:read"]).toBe("member");
    expect(can(makeActor({ role: "viewer" }), "activity:read", orgResource)).toBe(false);
    expect(can(makeActor({ role: "member" }), "activity:read", orgResource)).toBe(true);
  });

  it("requires every listed action to pass in the bulk form", () => {
    const admin = makeActor({ role: "admin" });
    expect(canAll(admin, ["member:read", "member:invite"], orgResource)).toBe(true);
    expect(canAll(admin, ["member:invite", "org:delete"], orgResource)).toBe(false);
    expect(canAll(makeActor({ role: "viewer" }), [], orgResource)).toBe(true);
  });

  it("reports `denied_unknown_action` for an action outside the vocabulary", () => {
    const decision = explain(
      makeActor({ role: "owner" }),
      "issue:teleport" as PermissionAction,
      orgResource,
    );
    expect(decision.allowed).toBe(false);
    expect(decision.reason).toBe("denied_unknown_action");
  });

  it("names the resource kind that was asked about", () => {
    const roles: readonly Role[] = ["owner", "viewer"];
    for (const role of roles) {
      expect(explain(makeActor({ role }), "org:read", orgResource).resourceKind).toBe(
        "organization",
      );
      expect(explain(makeActor({ role }), "issue:read", foreignOwned).resourceKind).toBe(
        "issue",
      );
    }
  });
});
/** Author/assignee escalations for issues and comments. */
import { describe, expect, it } from "vitest";
import { PermissionDeniedError, assertCan, can, explain } from "@/lib/permissions";
import type { CommentId, IssueId, MemberId, ProjectId } from "@/types/common";
import type { PermissionResource } from "@/types/permission";
import { ALICE, BOB, ORG_A, makeActor } from "../helpers/factories";

const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP" as ProjectId;

function issue(
  authorId = BOB,
  assigneeId: typeof ALICE | typeof BOB | null = null,
): PermissionResource {
  return {
    kind: "issue",
    orgId: ORG_A,
    projectId: PROJECT,
    issueId: "01HZZZSSSSSSSSSSSSSSSSSSSS" as IssueId,
    authorId,
    assigneeId,
  };
}

function comment(authorId = BOB): PermissionResource {
  return {
    kind: "comment",
    orgId: ORG_A,
    commentId: "01HZZZCCCCCCCCCCCCCCCCCCCC" as CommentId,
    authorId,
  };
}

const viewer = makeActor({ role: "viewer", userId: ALICE });

describe("permissions ownership escalations", () => {
  it("lets an author update their own issue despite lacking the role", () => {
    expect(can(viewer, "issue:update", issue(BOB))).toBe(false);
    expect(can(viewer, "issue:update", issue(ALICE))).toBe(true);
    expect(explain(viewer, "issue:update", issue(ALICE)).reason).toBe(
      "granted_by_ownership",
    );
  });

  it("lets the assignee update and archive an issue they did not author", () => {
    expect(can(viewer, "issue:update", issue(BOB, ALICE))).toBe(true);
    expect(can(viewer, "issue:archive", issue(BOB, ALICE))).toBe(true);
  });

  it("does not escalate deletion, which stays an admin action", () => {
    expect(can(viewer, "issue:delete", issue(ALICE, ALICE))).toBe(false);
    expect(explain(viewer, "issue:delete", issue(ALICE)).reason).toBe("denied_by_role");
  });

  it("lets a comment author edit and delete their own comment", () => {
    expect(can(viewer, "comment:update", comment(ALICE))).toBe(true);
    expect(can(viewer, "comment:delete", comment(ALICE))).toBe(true);
    expect(can(viewer, "comment:update", comment(BOB))).toBe(false);
    expect(can(viewer, "comment:delete", comment(BOB))).toBe(false);
  });

  it("does not escalate comment creation, which needs the member role", () => {
    expect(can(viewer, "comment:create", comment(ALICE))).toBe(false);
  });

  it("lets a recipient manage their own notification", () => {
    const own: PermissionResource = {
      kind: "notification",
      orgId: ORG_A,
      recipientId: ALICE,
    };
    const other: PermissionResource = {
      kind: "notification",
      orgId: ORG_A,
      recipientId: BOB,
    };
    // `notification:manage` is a viewer action anyway, so both pass by role.
    expect(can(viewer, "notification:manage", own)).toBe(true);
    expect(can(viewer, "notification:manage", other)).toBe(true);
  });

  it("does not escalate a project action for the project lead", () => {
    const led: PermissionResource = {
      kind: "project",
      orgId: ORG_A,
      projectId: PROJECT,
      visibility: "org",
      leadId: ALICE,
    };
    // `project:archive` is not in the escalation list, so the lead still needs admin.
    expect(can(viewer, "project:archive", led)).toBe(false);
    expect(can(makeActor({ role: "admin" }), "project:archive", led)).toBe(true);
  });

  it("does not let a member escalate their own role", () => {
    const self: PermissionResource = {
      kind: "member",
      orgId: ORG_A,
      memberId: "01HZZZMMMMMMMMMMMMMMMMMMMM" as MemberId,
      targetUserId: ALICE,
      targetRole: "member",
    };
    expect(can(makeActor({ role: "member" }), "member:update_role", self)).toBe(false);
  });

  it("keeps ownership subordinate to the tenant boundary", () => {
    const foreignActor = makeActor({ role: "viewer", userId: ALICE, orgId: ORG_A });
    const foreignIssue: PermissionResource = {
      ...issue(ALICE, ALICE),
      orgId: "01HZZZBBBBBBBBBBBBBBBBBBBB" as PermissionResource["orgId"],
    };
    expect(can(foreignActor, "issue:update", foreignIssue)).toBe(false);
    expect(explain(foreignActor, "issue:update", foreignIssue).reason).toBe(
      "denied_cross_tenant",
    );
  });

  it("throws PermissionDeniedError carrying the decision from assertCan", () => {
    expect(() => assertCan(viewer, "issue:update", issue(ALICE))).not.toThrow();
    expect(() => assertCan(viewer, "issue:update", issue(BOB))).toThrow(
      PermissionDeniedError,
    );

    try {
      assertCan(viewer, "issue:update", issue(BOB));
      expect.unreachable("assertCan should have thrown");
    } catch (error) {
      const denied = error as PermissionDeniedError;
      expect(denied.code).toBe("forbidden");
      expect(denied.action).toBe("issue:update");
      expect(denied.decision.reason).toBe("denied_by_role");
    }
  });
});
