"use server";

/**
 * Creates a project after the plan's project quota is checked.
 *
 * Owner D. Archived projects still occupy the quota, so the count deliberately
 * includes them — restoring a project must never be blocked by a limit the
 * restore itself would breach.
 *
 * Must call (do not reimplement): createProjectSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, projectTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createProjectSchema, type CreateProjectInput } from "@/schemas/project";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createProject } from "@/server/services/project-service";
import type { ActionResult } from "@/types/api";
import type { Project } from "@/types/project";

const run = withAction<typeof createProjectSchema, Project>(
  createProjectSchema,
  async (raw, actor) => {
    const input = raw as CreateProjectInput;

    const allowed = can(actor, "project:create", {
      kind: "project",
      orgId: input.orgId,
      projectId: PENDING_PROJECT_ID,
      visibility: input.visibility,
      leadId: input.leadId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("project:create");
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.projectsUsed >= limits.projects) {
      throw new PlanLimitError("projects", limits.projects, summary.usage.projectsUsed);
    }

    const project = await createProject(actor, input);
    revalidateTagged(
      [orgTag(input.orgId), projectTag(project.id)],
      CACHE_PROFILES.minutes,
    );
    return project;
  },
  { revalidate: ["projects"], cacheProfile: "minutes" },
);

export async function createProjectAction(raw: unknown): Promise<ActionResult<Project>> {
  return run(raw);
}
"use server";

/**
 * Invites one member; enforces the seat quota and the invite rate limit.
 *
 * Owner D. Pending invitations count against `seats` — otherwise an org on the
 * free plan could queue fifty invitations and blow past three seats the moment
 * they are accepted.
 *
 * Must call (do not reimplement): inviteMemberSchema, can, getPlanLimits,
 * consumeRateLimit, getActor, toActionResult
 */

import {
  ForbiddenActionError,
  PlanLimitError,
  RateLimitedError,
} from "@/actions/_lib/action-errors";
import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inviteMemberSchema, type InviteMemberInput } from "@/schemas/member";
import { inviteMember } from "@/server/services/invitation-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Invitation } from "@/types/member";

const INVITE_BUCKET = "member:invite";

const run = withAction<typeof inviteMemberSchema, Invitation>(
  inviteMemberSchema,
  async (raw, actor) => {
    const input = raw as InviteMemberInput;

    const allowed = can(actor, "member:invite", {
      kind: "member",
      orgId: input.orgId,
      memberId: PENDING_MEMBER_ID,
      targetUserId: actor.userId,
      targetRole: input.role,
    });
    if (!allowed) {
      throw new ForbiddenActionError("member:invite");
    }

    const verdict = await consumeRateLimit(input.orgId, INVITE_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(INVITE_BUCKET, verdict.resetAt);
    }

    const summary = await getOrganizationSummary(actor, input.orgId);
    const limits = getPlanLimits(summary.organization.plan);
    if (summary.usage.seatsUsed + 1 > limits.seats) {
      throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
    }

    const invitation = await inviteMember(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
    return invitation;
  },
  { revalidate: ["members", "invitations"], cacheProfile: "minutes" },
);

export async function inviteMemberAction(raw: unknown): Promise<ActionResult<Invitation>> {
  return run(raw);
}
"use server";

/**
 * Creates an issue after the per-project quota check.
 *
 * Owner D. The quota is read from `@/config/plan-limits` rather than hard-coded
 * here — the plan of the owning organization decides `issuesPerProject`.
 *
 * Must call (do not reimplement): createIssueSchema, can, getPlanLimits,
 * getActor, toActionResult
 */

import { withAction } from "@/actions/_lib/with-action";
import { ForbiddenActionError, PlanLimitError } from "@/actions/_lib/action-errors";
import { getPlanLimits } from "@/config/plan-limits";
import { issueTag, orgTag, projectTag, revalidateTagged, CACHE_PROFILES } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { createIssueSchema, type CreateIssueInput } from "@/schemas/issue";
import { createIssue, listIssues } from "@/server/services/issue-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

const run = withAction<typeof createIssueSchema, Issue>(
  createIssueSchema,
  async (raw, actor) => {
    const input = raw as CreateIssueInput;

    const allowed = can(actor, "issue:create", {
      kind: "issue",
      orgId: input.orgId,
      projectId: input.projectId,
      issueId: "" as Issue["id"],
      authorId: actor.userId,
      assigneeId: input.assigneeId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("issue:create");
    }

    await assertProjectHasRoom(actor, input);

    const issue = await createIssue(actor, input);

    revalidateTagged(
      [orgTag(input.orgId), projectTag(input.projectId), issueTag(issue.id)],
      CACHE_PROFILES.minutes,
    );
    return issue;
  },
  { revalidate: ["issues"], cacheProfile: "minutes" },
);

/**
 * Counts the issues already living in the project and compares them with the
 * plan's `issuesPerProject` ceiling. Archived issues still occupy the quota,
 * which is why the count deliberately includes them.
 */
async function assertProjectHasRoom(
  actor: Actor,
  input: CreateIssueInput,
): Promise<void> {
  const summary = await getOrganizationSummary(actor, input.orgId);
  const limits = getPlanLimits(summary.organization.plan);

  const existing = await listIssues(actor, {
    orgId: input.orgId,
    projectId: input.projectId,
    limit: 1,
    includeArchived: true,
  });

  if (existing.total >= limits.issuesPerProject) {
    throw new PlanLimitError("issuesPerProject", limits.issuesPerProject, existing.total);
  }
}

export async function createIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
  return run(raw);
}
"use server";

/**
 * Registers a webhook endpoint; plan and flag gated.
 *
 * Owner D. Two independent gates: the `webhooks` feature flag (which is itself
 * plan-derived) and the numeric `webhooks` quota. Both are checked because a
 * flag can be force-enabled through an org override while the quota still
 * applies.
 *
 * Must call (do not reimplement): createWebhookSchema, can, isEnabled,
 * getPlanLimits, getActor, toActionResult
 */

import {
  FeatureUnavailableError,
  ForbiddenActionError,
  PlanLimitError,
} from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { getPlanLimits } from "@/config/plan-limits";
import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { createWebhookSchema, type CreateWebhookInput } from "@/schemas/webhook";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { createWebhook, listWebhooks } from "@/server/services/webhook-service";
import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
import type { ActionResult } from "@/types/api";

const run = withAction<typeof createWebhookSchema, WebhookEndpointRow>(
  createWebhookSchema,
  async (raw, actor) => {
    const input = raw as CreateWebhookInput;

    const allowed = can(actor, "webhook:manage", {
      kind: "webhook",
      orgId: input.orgId,
      webhookId: null,
    });
    if (!allowed) {
      throw new ForbiddenActionError("webhook:manage");
    }

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    if (!isEnabled("webhooks", buildFlagContext(actor, organization))) {
      throw new FeatureUnavailableError("webhooks");
    }

    const limits = getPlanLimits(organization.plan);
    const existing = await listWebhooks(actor, input.orgId);
    if (existing.length >= limits.webhooks) {
      throw new PlanLimitError("webhooks", limits.webhooks, existing.length);
    }

    const endpoint = await createWebhook(actor, input);
    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.hours);
    return endpoint;
  },
  { revalidate: ["webhooks"], cacheProfile: "hours" },
);

export async function createWebhookAction(
  raw: unknown,
): Promise<ActionResult<WebhookEndpointRow>> {
  return run(raw);
}
/**
 * Invitation landing page; accepts or explains an expired token.
 *
 * Owner D. Dynamic, because whether the visitor already has a session decides
 * what they are shown: signed in, they get an accept button; signed out, they
 * are sent to the sign-in form with the invite as the destination.
 *
 * The token itself is never resolved here — `InvitationService` is the only
 * thing that may look one up, and only when it is being consumed.
 */

import Link from "next/link";
import { redirect } from "next/navigation";
import type { Metadata } from "next";
import { getSessionPrincipal } from "@/lib/session";
import { invitationTokenSchema } from "@/schemas/invitation";
import { InviteAcceptForm } from "./invite-accept-form";

type PageParams = { token: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "You have been invited",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { token } = await props.params;
  const search = await props.searchParams;

  const parsed = invitationTokenSchema.safeParse(token);
  if (!parsed.success) {
    return (
      <div className="space-y-3">
        <h1 className="text-lg font-semibold">This invitation is not valid</h1>
        <p className="text-sm text-slate-600">
          The link may have been truncated by an email client, or the invitation
          may have been revoked. Ask whoever invited you to send a new one.
        </p>
        <Link href="/login" className="text-sm text-indigo-600">
          Go to sign in
        </Link>
      </div>
    );
  }

  const principal = await getSessionPrincipal();
  if (principal === null) {
    redirect(`/login?next=${encodeURIComponent(`/invite/${token}`)}`);
  }

  const orgSlug = typeof search.org === "string" ? search.org : null;

  return (
    <div className="space-y-5">
      <div className="space-y-2">
        <h1 className="text-lg font-semibold">You have been invited</h1>
        <p className="text-sm text-slate-600">
          Accepting adds {principal.email} to the organization and takes up one
          of its seats.
        </p>
      </div>

      <InviteAcceptForm token={parsed.data} orgSlug={orgSlug} />
    </div>
  );
}
/**
 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
 * affected tags.
 *
 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
 * things each one must do — validate, authenticate, translate errors,
 * revalidate — happen in exactly one place.
 *
 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 */

import { getActor, requireActorFor } from "@/lib/actor";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ZodType } from "zod";
import { UnauthorizedActionError } from "./action-errors";

/** The body of an action: already-validated input plus the resolved principal. */
export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;

export type ActionOptions = {
  /**
   * When `true` (the default) the organization is taken from the parsed input —
   * either an `orgSlug` or an `orgId` field. When `false` the action does not
   * name an organization and the session's active org is used instead.
   */
  requireOrg?: boolean;
  /** Static cache tags invalidated once the handler resolves. */
  revalidate?: readonly string[];
  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
  cacheProfile?: string;
};

type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };

/**
 * Resolves the actor for one action call.
 *
 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 * instead resolve through `requireActorFor()`.
 */
async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
  if (fromInput && typeof input === "object" && input !== null) {
    const record = input as OrgBearingInput;
    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
      return getActor(record.orgSlug);
    }
    if (typeof record.orgId === "string" && record.orgId.length > 0) {
      return requireActorFor(record.orgId as OrgId);
    }
  }

  const principal = await getSessionPrincipal();
  if (principal === null || principal.activeOrgId === null) {
    throw new UnauthorizedActionError();
  }
  return requireActorFor(principal.activeOrgId);
}

/** Adds the monotonic token `useActionState` uses to tell two results apart. */
function stamp<T>(result: ActionResult<T>): ActionResult<T> {
  const submittedAt = new Date().toISOString();
  return result.ok
    ? { ok: true, data: result.data, submittedAt }
    : { ok: false, error: result.error, submittedAt };
}

export function withAction<TSchema extends ZodType, TData>(
  schema: TSchema,
  handler: ActionHandler,
  options: ActionOptions = {},
): (raw: unknown) => Promise<ActionResult<TData>> {
  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    const parsed = schema.safeParse(raw);
    if (!parsed.success) {
      return stamp(toActionResult(parsed.error));
    }

    try {
      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
      const data = (await handler(parsed.data, actor)) as TData;

      const tags = options.revalidate ?? [];
      if (tags.length > 0) {
        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
      }

      return stamp({ ok: true, data });
    } catch (error) {
      return stamp(toActionResult(error));
    }
  };
}
/**
 * Error types raised by Server Actions that are *expected* failures rather
 * than bugs. Each one carries the `ErrorCode` that `toAppError()` maps into
 * the `AppErrorShape` the client form layer renders, mirroring the convention
 * already used by `PermissionDeniedError` and `TenantScopeError`.
 *
 * These live in `src/actions/_lib` because only the action layer produces
 * them — services throw their own domain errors, and repositories throw none.
 */

import type { LimitedResource } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import type { PermissionAction } from "@/types/permission";

/** No session at all, or a session whose active organization is gone. */
export class UnauthorizedActionError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedActionError";
  }
}

/**
 * `can()` returned false. Distinct from `PermissionDeniedError` (thrown by
 * `assertCan()` inside services) only in that the action layer already knows
 * the action name and does not need the full `PermissionDecision`.
 */
export class ForbiddenActionError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly action: PermissionAction) {
    super(`Permission denied: ${action}`);
    this.name = "ForbiddenActionError";
  }
}

/** A plan quota from `@/config/plan-limits` would be breached. */
export class PlanLimitError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly resource: LimitedResource,
    readonly limit: number,
    readonly used: number,
  ) {
    super(`Plan limit reached for ${resource}: ${used}/${limit}`);
    this.name = "PlanLimitError";
  }
}

/** The token bucket in `@/lib/rate-limit` refused the request. */
export class RateLimitedError extends Error {
  readonly code = "rate_limited" as const;

  constructor(
    readonly bucketKey: string,
    readonly resetAt: IsoTimestamp,
  ) {
    super(`Rate limit exceeded for ${bucketKey}; retry after ${resetAt}`);
    this.name = "RateLimitedError";
  }
}

/** A feature flag that gates the whole action is off for this organization. */
export class FeatureUnavailableError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: string) {
    super(`Feature not available: ${flag}`);
    this.name = "FeatureUnavailableError";
  }
}

/** The row the action addresses does not exist inside the actor's tenant. */
export class ActionNotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(readonly what: string) {
    super(`Not found: ${what}`);
    this.name = "ActionNotFoundError";
  }
}
/**
 * Validated environment access. Nothing else in Taskflow reads `process.env`
 * — call sites import `env` (or `loadEnv()` when they need to validate a
 * different source, as the tests do) so a missing or malformed variable fails
 * once, loudly, instead of surfacing as `undefined` deep in a request.
 */
import { SITE_CONFIG } from "./site";

export type AppEnv = {
  nodeEnv: "development" | "test" | "production";
  databasePath: string;
  appUrl: string;
  digestEnabled: boolean;
};

const NODE_ENVS = ["development", "test", "production"] as const;

type NodeEnvValue = (typeof NODE_ENVS)[number];

function readNodeEnv(raw: string | undefined): NodeEnvValue {
  const value = (raw ?? "development").trim();
  const match = NODE_ENVS.find((candidate) => candidate === value);
  return match ?? "development";
}

/** Accepts `1`/`true`/`yes`/`on` (case-insensitive) as true; anything else false. */
function readBoolean(raw: string | undefined, fallback: boolean): boolean {
  if (raw === undefined || raw.trim() === "") return fallback;
  const value = raw.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(value)) return true;
  if (["0", "false", "no", "off"].includes(value)) return false;
  throw new Error(`Invalid boolean environment value: "${raw}"`);
}

function readUrl(raw: string | undefined, fallback: string): string {
  const value = (raw ?? "").trim() || fallback;
  try {
    // Normalises away a trailing slash so `${appUrl}${path}` never doubles up.
    const parsed = new URL(value);
    return parsed.origin + parsed.pathname.replace(/\/$/, "");
  } catch {
    throw new Error(`Invalid TASKFLOW_APP_URL: "${value}"`);
  }
}

/**
 * Reads and validates the environment. Defaults are chosen so a fresh
 * checkout runs with no `.env` at all — the corpus must build offline.
 */
export function loadEnv(source: NodeJS.ProcessEnv = process.env): AppEnv {
  const nodeEnv = readNodeEnv(source.NODE_ENV);
  const databasePath =
    (source.TASKFLOW_DB_PATH ?? "").trim() ||
    (nodeEnv === "test" ? ":memory:" : "./data/taskflow.db");

  return {
    nodeEnv,
    databasePath,
    appUrl: readUrl(source.TASKFLOW_APP_URL, SITE_CONFIG.url),
    digestEnabled: readBoolean(source.TASKFLOW_DIGEST_ENABLED, nodeEnv !== "test"),
  };
}

export const env: AppEnv = loadEnv();
