/** Throwing form used by the create paths, and it emits the breach event. */
export async function assertWithinLimit(
  orgId: OrgId,
  resource: LimitedResource,
  requested = 1,
): Promise<void> {
  const check = await checkLimit(orgId, resource, requested);
  if (!check.exceeded) return;

  await reportLimitExceeded(orgId, resource, check.plan, check.used);

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/** Report a refused write using the usage measured by that write's guard. */
export async function reportLimitExceeded(
  orgId: OrgId,
  resource: LimitedResource,
  plan: PlanId,
  used: number,
  actorId: UserId | null = null,
): Promise<void> {
  await emit("billing.limit_exceeded", {
    orgId,
    actorId,
    occurredAt: toIsoTimestamp(new Date()),
    resource,
    limit: getLimit(plan, resource),
    used,
  });
}

